"use client";

import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  ArrowLeft, ArrowRight, CalendarDays, Check, ChevronLeft, ChevronRight, CircleDollarSign,
  Clock3, LayoutDashboard, Menu, Pencil, Plus, RefreshCw, Scissors, Search, Settings,
  Trash2, UserRound, Users, X,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { money } from "../data";

type Section = "today" | "calendar" | "clients" | "services" | "team" | "settings";
type Appointment = { id:string; publicToken:string; clientId:string; clientName:string; phone:string; email?:string|null; notes?:string|null; serviceId:string; barberId:string; date:string; time:string; price:number; status:string; startAt:number; endAt:number };
type Client = { id:string; name:string; phone:string; email?:string|null; preferredBarber?:string|null; notes?:string|null; visitCount:number; createdAt:number };
type ServiceRow = { id:string; nameEs:string; nameEn:string; price:number; minutes:number; active:boolean; featured:boolean; sortOrder:number };
type BarberRow = { id:string; name:string; handle?:string|null; specialties?:string|null; phone?:string|null; color:string; active:boolean; workingHours:string };
type Block = { id:string; barberId:string; startAt:number; endAt:number; reason:string; createdAt:number };
type WaitlistEntry = { id:string; name:string; phone:string; serviceId:string; barberId?:string|null; preferredDate:string; preferredTime?:string|null; status:string; createdAt:number };
type StudioData = { appointments:Appointment[]; clients:Client[]; services:ServiceRow[]; barbers:BarberRow[]; blockedTime:Block[]; waitlist:WaitlistEntry[]; settings:Record<string,string> };

const emptyData:StudioData={appointments:[],clients:[],services:[],barbers:[],blockedTime:[],waitlist:[],settings:{}};
const statusMap:Record<string,{label:string;style:string}>={
  pending:{label:"Pendiente",style:"bg-amber-400/15 text-amber-300"},confirmed:{label:"Confirmada",style:"bg-blue-400/15 text-blue-300"},
  arrived:{label:"Llegó",style:"bg-violet-400/15 text-violet-300"},in_progress:{label:"En silla",style:"bg-[#e84c3d]/15 text-[#ff7164]"},
  completed:{label:"Completada",style:"bg-emerald-400/15 text-emerald-300"},cancelled:{label:"Cancelada",style:"bg-red-400/15 text-red-300"},
  no_show:{label:"No llegó",style:"bg-zinc-400/15 text-zinc-300"},
};
const sectionMeta:Record<Section,{title:string;description:string}>={
  today:{title:"Hoy en Jota Eme",description:"Control central de la operación"},
  calendar:{title:"Calendario",description:"Citas y bloqueos por barbero"},
  clients:{title:"Clientes",description:"Historial, preferencias y próximas visitas"},
  services:{title:"Servicios",description:"Precios, duración y disponibilidad"},
  team:{title:"Equipo",description:"Barberos, horarios y capacidad"},
  settings:{title:"Configuración",description:"Reglas que controlan las reservas"},
};
const dayKeys=["monday","tuesday","wednesday","thursday","friday","saturday","sunday"];
const dayNames:Record<string,string>={monday:"Lun",tuesday:"Mar",wednesday:"Mié",thursday:"Jue",friday:"Vie",saturday:"Sáb",sunday:"Dom"};
const activeStatuses=new Set(["pending","confirmed","arrived","in_progress"]);
const dateInput=(date:Date)=>new Intl.DateTimeFormat("en-CA",{timeZone:"America/Bogota"}).format(date);
const parseDate=(value:string)=>new Date(value+"T12:00:00");
const addDays=(value:string,days:number)=>{const date=parseDate(value);date.setDate(date.getDate()+days);return dateInput(date)};
const dateLabel=(value:string,options:Intl.DateTimeFormatOptions={weekday:"short",month:"short",day:"numeric"})=>new Intl.DateTimeFormat("es-CO",options).format(parseDate(value));
const initials=(name:string)=>name.split(" ").map(part=>part[0]).slice(0,2).join("").toUpperCase();

async function api<T=any>(path:string,init?:RequestInit):Promise<T>{
  const response=await fetch(path,init);
  if(response.status===401){window.location.assign("/admin/login");throw new Error("Sesión vencida");}
  const data:any=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(data.error??"No pudimos completar la acción.");
  return data;
}

export function AdminDashboard({userName}:{userName:string}){
  const [data,setData]=useState<StudioData>(emptyData);
  const [loading,setLoading]=useState(true);
  const [loadError,setLoadError]=useState("");
  const [notice,setNotice]=useState("");
  const [section,setSection]=useState<Section>("today");
  const [sidebar,setSidebar]=useState(false);
  const [searchOpen,setSearchOpen]=useState(false);
  const [appointmentOpen,setAppointmentOpen]=useState(false);
  const [blockOpen,setBlockOpen]=useState(false);
  const [waitlistOpen,setWaitlistOpen]=useState(false);
  const [selectedAppointment,setSelectedAppointment]=useState<Appointment|null>(null);
  const [selectedClient,setSelectedClient]=useState<Client|null>(null);
  const [selectedService,setSelectedService]=useState<ServiceRow|null>(null);
  const [selectedBarber,setSelectedBarber]=useState<BarberRow|null>(null);

  const refresh=useCallback(async(silent=false)=>{
    if(!silent)setLoading(true);
    try{setData(await api("/api/admin/studio"));setLoadError("");}
    catch(error){setLoadError(error instanceof Error?error.message:"No pudimos cargar Studio OS.");}
    finally{setLoading(false);}
  },[]);
  useEffect(()=>{void refresh()},[refresh]);
  useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(""),3500);return()=>clearTimeout(timer)},[notice]);

  const today=dateInput(new Date());
  const now=Math.floor(Date.now()/1000);
  const todayAppointments=useMemo(()=>data.appointments.filter(a=>a.date===today),[data.appointments,today]);
  const upcoming=useMemo(()=>data.appointments.filter(a=>a.startAt>=now&&activeStatuses.has(a.status)).sort((a,b)=>a.startAt-b.startAt),[data.appointments,now]);
  const nextAppointment=upcoming[0];
  const revenue=useMemo(()=>todayAppointments.filter(a=>!["cancelled","no_show"].includes(a.status)).reduce((sum,a)=>sum+a.price,0),[todayAppointments]);
  const waitingCount=data.waitlist.filter(entry=>entry.status==="waiting").length;
  const serviceName=(id:string)=>data.services.find(service=>service.id===id)?.nameEs??id;
  const barberName=(id:string)=>data.barbers.find(barber=>barber.id===id)?.name??id;
  const chooseSection=(value:Section)=>{setSection(value);setSidebar(false)};
  const success=(message:string)=>{setNotice(message);void refresh(true)};
  const signOut=async()=>{await fetch("/api/admin/session",{method:"DELETE"});window.location.assign("/admin/login")};

  return <main className="min-h-screen bg-[#0b0b0a] text-[#f4f1e8]">
    <aside className={`fixed inset-y-0 left-0 z-50 w-72 border-r border-white/10 bg-[#11110f] p-5 transition lg:translate-x-0 ${sidebar?"translate-x-0":"-translate-x-full"}`}>
      <button onClick={()=>setSidebar(false)} className="absolute right-4 top-4 lg:hidden" aria-label="Cerrar menú"><X/></button>
      <Link href="/" className="mb-10 flex items-center gap-3"><img src="/jota-eme-logo.jpg" alt="Jota Eme" className="h-12 w-12 rounded-full bg-white object-cover"/><span><b className="display block text-xl">Jota Eme</b><small className="text-[10px] font-bold tracking-[.18em] text-white/35">STUDIO OS</small></span></Link>
      <p className="eyebrow mb-3 text-white/30">OPERACIONES</p>
      <nav className="space-y-1">
        {([[LayoutDashboard,"Hoy","today"],[CalendarDays,"Calendario","calendar"],[Users,"Clientes","clients"],[Scissors,"Servicios","services"],[UserRound,"Equipo","team"],[Settings,"Configuración","settings"]] as const).map(([Icon,label,value])=>
          <button key={value} onClick={()=>chooseSection(value)} className={`flex h-12 w-full items-center gap-3 px-4 text-left text-sm font-semibold transition ${section===value?"bg-[#e84c3d] text-black":"text-white/55 hover:bg-white/[.05] hover:text-white"}`}><Icon size={18}/>{label}</button>)}
      </nav>
      <div className="mt-8 border-t border-white/10 pt-5 lg:absolute lg:inset-x-5 lg:bottom-5"><p className="truncate text-sm font-semibold">{userName}</p><button onClick={signOut} className="mt-1 text-xs text-white/35 hover:text-white">Cerrar sesión</button></div>
    </aside>
    {sidebar&&<button className="fixed inset-0 z-40 bg-black/65 lg:hidden" onClick={()=>setSidebar(false)} aria-label="Cerrar menú"/>}

    <div className="lg:pl-72">
      <header className="sticky top-0 z-30 flex min-h-[72px] items-center justify-between gap-3 border-b border-white/10 bg-[#0b0b0a]/92 px-4 py-3 backdrop-blur-xl sm:px-7">
        <div className="flex min-w-0 items-center gap-3"><button onClick={()=>setSidebar(true)} className="lg:hidden" aria-label="Abrir menú"><Menu/></button><div className="min-w-0"><h1 className="truncate text-xl font-black">{sectionMeta[section].title}</h1><p className="truncate text-xs text-white/35">{sectionMeta[section].description}</p></div></div>
        <div className="flex items-center gap-2"><button onClick={()=>setSearchOpen(true)} className="flex h-10 items-center gap-2 border border-white/10 px-3 text-sm text-white/60 hover:border-white/30"><Search size={16}/><span className="hidden sm:inline">Buscar</span></button><Button onClick={()=>setAppointmentOpen(true)} className="h-10 rounded-none font-black"><Plus/><span className="hidden sm:inline">NUEVA CITA</span></Button></div>
      </header>
      <div className="mx-auto max-w-[1600px] p-4 sm:p-7">
        {notice&&<div className="fixed right-4 top-20 z-[70] flex max-w-sm items-center gap-3 border border-emerald-400/25 bg-[#102018] px-4 py-3 text-sm text-emerald-200 shadow-2xl"><Check size={18}/>{notice}</div>}
        {loadError&&<div className="mb-5 flex items-center justify-between gap-4 border border-red-400/25 bg-red-400/10 p-4 text-sm text-red-100"><span>{loadError}</span><button onClick={()=>refresh()} className="flex items-center gap-2 font-bold"><RefreshCw size={15}/> Reintentar</button></div>}
        {loading?<LoadingState/>:<>
          {section==="today"&&<TodayView data={data} today={today} revenue={revenue} next={nextAppointment} waitingCount={waitingCount} serviceName={serviceName} barberName={barberName} onAppointment={setSelectedAppointment} onNew={()=>setAppointmentOpen(true)} onBlock={()=>setBlockOpen(true)} onWaitlist={()=>setWaitlistOpen(true)} onStatus={async(id,status)=>{await api("/api/admin/appointments",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id,status})});success("Estado de la cita actualizado.")}}/>}
          {section==="calendar"&&<CalendarView appointments={data.appointments} blocks={data.blockedTime} barbers={data.barbers} services={data.services} today={today} onAppointment={setSelectedAppointment} onNew={()=>setAppointmentOpen(true)} onBlock={()=>setBlockOpen(true)} onDeleteBlock={async id=>{await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"block:delete",id})});success("Bloqueo eliminado.")}}/>}
          {section==="clients"&&<ClientsView clients={data.clients} appointments={data.appointments} serviceName={serviceName} barberName={barberName} onClient={setSelectedClient}/>}
          {section==="services"&&<ServicesView services={data.services} onEdit={setSelectedService}/>}
          {section==="team"&&<TeamView barbers={data.barbers} appointments={data.appointments} today={today} onEdit={setSelectedBarber} onBlock={()=>setBlockOpen(true)}/>}
          {section==="settings"&&<SettingsView settings={data.settings} onSave={async value=>{await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"settings:save",value})});success("Configuración guardada.")}}/>}
        </>}
      </div>
    </div>

    <SearchDialog open={searchOpen} onOpenChange={setSearchOpen} data={data} serviceName={serviceName} barberName={barberName} onAppointment={item=>{setSearchOpen(false);setSelectedAppointment(item)}} onClient={item=>{setSearchOpen(false);setSelectedClient(item)}}/>
    <AppointmentDialog open={appointmentOpen||!!selectedAppointment} onOpenChange={open=>{if(!open){setAppointmentOpen(false);setSelectedAppointment(null)}}} appointment={selectedAppointment} services={data.services.filter(s=>s.active)} barbers={data.barbers.filter(b=>b.active)} onSaved={()=>{setAppointmentOpen(false);setSelectedAppointment(null);success(selectedAppointment?"Cita actualizada.":"Cita guardada.")}}/>
    <BlockDialog open={blockOpen} onOpenChange={setBlockOpen} barbers={data.barbers.filter(b=>b.active)} onSaved={()=>{setBlockOpen(false);success("Tiempo bloqueado en el calendario.")}}/>
    <WaitlistDialog open={waitlistOpen} onOpenChange={setWaitlistOpen} entries={data.waitlist} services={data.services} barbers={data.barbers} onChanged={message=>success(message)}/>
    <ClientDialog client={selectedClient} open={!!selectedClient} onOpenChange={open=>{if(!open)setSelectedClient(null)}} barbers={data.barbers} appointments={data.appointments} serviceName={serviceName} onSaved={()=>{setSelectedClient(null);success("Perfil del cliente actualizado.")}}/>
    <ServiceDialog service={selectedService} open={!!selectedService} onOpenChange={open=>{if(!open)setSelectedService(null)}} onSaved={()=>{setSelectedService(null);success("Servicio actualizado. Los cambios ya controlan nuevas reservas.")}}/>
    <BarberDialog barber={selectedBarber} open={!!selectedBarber} onOpenChange={open=>{if(!open)setSelectedBarber(null)}} onSaved={()=>{setSelectedBarber(null);success("Barbero y horario actualizados.")}}/>
  </main>;
}

function LoadingState(){return <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{Array.from({length:8},(_,i)=><div key={i} className="h-36 animate-pulse border border-white/10 bg-white/[.04]"/>)}</div>}

function TodayView({data,today,revenue,next,waitingCount,serviceName,barberName,onAppointment,onNew,onBlock,onWaitlist,onStatus}:{data:StudioData;today:string;revenue:number;next?:Appointment;waitingCount:number;serviceName:(id:string)=>string;barberName:(id:string)=>string;onAppointment:(a:Appointment)=>void;onNew:()=>void;onBlock:()=>void;onWaitlist:()=>void;onStatus:(id:string,status:string)=>Promise<void>}){
  const todays=data.appointments.filter(a=>a.date===today).sort((a,b)=>a.startAt-b.startAt);
  const active=data.barbers.filter(b=>b.active);
  const completed=todays.filter(a=>a.status==="completed").length;
  return <div className="space-y-5">
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
      <Metric icon={CalendarDays} label="Citas hoy" value={todays.length} note={`${completed} completadas`}/>
      <Metric icon={Clock3} label="Próxima cita" value={next?.time??"—"} note={next?`${next.clientName} · ${dateLabel(next.date)}`:"Sin citas próximas"}/>
      <Metric icon={CircleDollarSign} label="Ingresos estimados" value={money(revenue)} note="Reservas activas de hoy"/>
      <Metric icon={Users} label="Lista de espera" value={waitingCount} note="Clientes esperando un espacio"/>
    </section>
    <section className="grid gap-5 xl:grid-cols-[1fr_340px]">
      <div className="border border-white/10 bg-[#141412]">
        <div className="flex items-center justify-between border-b border-white/10 p-5"><div><h2 className="text-xl font-black">Tablero de hoy</h2><p className="mt-1 text-sm text-white/40">{dateLabel(today,{weekday:"long",month:"long",day:"numeric"})}</p></div><Button onClick={onNew} className="rounded-none"><Plus/> Agregar</Button></div>
        <div className="divide-y divide-white/10">
          {!todays.length&&<Empty title="La agenda está abierta" detail="Agrega un walk-in o deja el espacio disponible para reservas." action="AGREGAR CITA" onAction={onNew}/>}
          {todays.map(appointment=><button key={appointment.id} onClick={()=>onAppointment(appointment)} className="grid w-full gap-3 p-4 text-left transition hover:bg-white/[.035] sm:grid-cols-[95px_1fr_170px_auto] sm:items-center">
            <b className="text-lg">{appointment.time}</b><span><b className="block">{appointment.clientName}</b><small className="text-white/40">{serviceName(appointment.serviceId)} · {appointment.phone}</small></span><span className="text-sm text-white/55">{barberName(appointment.barberId)}</span><Status status={appointment.status}/></button>)}
        </div>
      </div>
      <aside className="space-y-5">
        {next&&<div className="border border-[#e84c3d]/35 bg-[#e84c3d]/[.07] p-5"><p className="eyebrow text-[#ff7164]">SIGUIENTE</p><button onClick={()=>onAppointment(next)} className="mt-5 flex w-full items-center gap-3 text-left"><span className="grid h-12 w-12 shrink-0 place-items-center bg-[#e84c3d] font-black text-black">{initials(next.clientName)}</span><span><b>{next.clientName}</b><small className="block text-white/45">{serviceName(next.serviceId)} · {barberName(next.barberId)}</small><small className="block text-white/45">{dateLabel(next.date)} · {next.time}</small></span></button><div className="mt-5 grid grid-cols-2 gap-2"><button onClick={()=>onStatus(next.id,"arrived")} className="h-11 bg-[#e84c3d] text-xs font-black text-black">MARCAR LLEGÓ</button><a href={`https://wa.me/${next.phone.replace(/\D/g,"")}`} target="_blank" rel="noreferrer" className="grid h-11 place-items-center border border-white/15 text-xs font-bold">WHATSAPP</a></div></div>}
        <div className="border border-white/10 bg-[#141412] p-5"><h2 className="font-black">Acciones rápidas</h2><div className="mt-4 space-y-2"><Quick icon={Plus} label="Agregar walk-in" onClick={onNew}/><Quick icon={Clock3} label="Bloquear tiempo" onClick={onBlock}/><Quick icon={Users} label={`Lista de espera · ${waitingCount}`} onClick={onWaitlist}/></div></div>
        <div className="border border-white/10 bg-[#141412] p-5"><h2 className="font-black">Carga por barbero</h2><div className="mt-4 space-y-4">{active.map(barber=>{const count=todays.filter(a=>a.barberId===barber.id&&!["cancelled","no_show"].includes(a.status)).length;return <div key={barber.id}><div className="mb-2 flex justify-between text-sm"><span>{barber.name}</span><b>{count} citas</b></div><div className="h-1.5 bg-white/10"><div className="h-full" style={{width:`${Math.min(100,count/8*100)}%`,background:barber.color}}/></div></div>})}</div></div>
      </aside>
    </section>
  </div>
}

function Metric({icon:Icon,label,value,note}:{icon:typeof CalendarDays;label:string;value:string|number;note:string}){return <article className="border border-white/10 bg-[#141412] p-5"><div className="flex justify-between"><span className="text-sm text-white/45">{label}</span><Icon size={19} className="text-[#e84c3d]"/></div><b className="mt-5 block text-3xl">{value}</b><small className="mt-2 block text-white/30">{note}</small></article>}
function Quick({icon:Icon,label,onClick}:{icon:typeof Plus;label:string;onClick:()=>void}){return <button onClick={onClick} className="flex h-12 w-full items-center gap-3 border border-white/10 px-4 text-sm hover:border-[#e84c3d]"><Icon size={17}/>{label}</button>}
function Status({status}:{status:string}){const item=statusMap[status]??{label:status,style:"bg-white/10 text-white/60"};return <span className={`w-fit px-2.5 py-1 text-xs font-bold ${item.style}`}>{item.label}</span>}

function CalendarView({appointments,blocks,barbers,services,today,onAppointment,onNew,onBlock,onDeleteBlock}:{appointments:Appointment[];blocks:Block[];barbers:BarberRow[];services:ServiceRow[];today:string;onAppointment:(a:Appointment)=>void;onNew:()=>void;onBlock:()=>void;onDeleteBlock:(id:string)=>Promise<void>}){
  const [mode,setMode]=useState<"day"|"week"|"month">("week");
  const [focus,setFocus]=useState(today);
  const [barber,setBarber]=useState("all");
  const serviceName=(id:string)=>services.find(s=>s.id===id)?.nameEs??id;
  const barberName=(id:string)=>barbers.find(b=>b.id===id)?.name??id;
  const filtered=appointments.filter(a=>barber==="all"||a.barberId===barber);
  const move=(direction:number)=>setFocus(addDays(focus,direction*(mode==="day"?1:mode==="week"?7:30)));
  const weekStart=useMemo(()=>{const d=parseDate(focus);const offset=(d.getDay()+6)%7;d.setDate(d.getDate()-offset);return dateInput(d)},[focus]);
  const weekDays=Array.from({length:7},(_,i)=>addDays(weekStart,i));
  const monthStart=`${focus.slice(0,7)}-01`;const first=parseDate(monthStart);const monthGridStart=addDays(monthStart,-((first.getDay()+6)%7));const monthDays=Array.from({length:42},(_,i)=>addDays(monthGridStart,i));
  const dayBlocks=(date:string)=>blocks.filter(block=>{const blockDate=dateInput(new Date(block.startAt*1000));return blockDate===date&&(barber==="all"||block.barberId===barber)});
  return <div className="border border-white/10 bg-[#141412]">
    <div className="flex flex-col gap-4 border-b border-white/10 p-4 lg:flex-row lg:items-center lg:justify-between">
      <div className="flex items-center gap-2"><button onClick={()=>move(-1)} className="grid h-10 w-10 place-items-center border border-white/10"><ChevronLeft/></button><button onClick={()=>setFocus(today)} className="h-10 border border-white/10 px-4 text-sm font-bold">HOY</button><button onClick={()=>move(1)} className="grid h-10 w-10 place-items-center border border-white/10"><ChevronRight/></button><h2 className="ml-2 text-lg font-black capitalize">{mode==="month"?dateLabel(focus,{month:"long",year:"numeric"}):dateLabel(focus,{weekday:"long",month:"long",day:"numeric"})}</h2></div>
      <div className="flex flex-wrap gap-2"><select value={barber} onChange={e=>setBarber(e.target.value)} className="h-10 border border-white/10 bg-[#111] px-3 text-sm"><option value="all">Todos los barberos</option>{barbers.filter(b=>b.active).map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><div className="flex border border-white/10">{(["day","week","month"] as const).map(value=><button key={value} onClick={()=>setMode(value)} className={`h-10 px-4 text-xs font-bold ${mode===value?"bg-[#e84c3d] text-black":"text-white/50"}`}>{value==="day"?"DÍA":value==="week"?"SEMANA":"MES"}</button>)}</div><button onClick={onBlock} className="h-10 border border-white/10 px-4 text-xs font-bold"><Clock3 className="mr-2 inline" size={15}/>BLOQUEAR</button></div>
    </div>
    {mode==="day"&&<div className="p-4"><DayColumn date={focus} appointments={filtered.filter(a=>a.date===focus)} blocks={dayBlocks(focus)} serviceName={serviceName} barberName={barberName} onAppointment={onAppointment} onNew={onNew} onDeleteBlock={onDeleteBlock}/></div>}
    {mode==="week"&&<div className="grid min-w-[900px] grid-cols-7 overflow-x-auto">{weekDays.map(date=><div key={date} className={`min-h-[560px] border-r border-white/10 p-2 ${date===today?"bg-[#e84c3d]/[.035]":""}`}><div className="mb-3 border-b border-white/10 pb-3 text-center"><small className="uppercase text-white/35">{dateLabel(date,{weekday:"short"})}</small><b className={`mx-auto mt-1 grid h-8 w-8 place-items-center rounded-full ${date===today?"bg-[#e84c3d] text-black":""}`}>{parseDate(date).getDate()}</b></div><div className="space-y-2">{filtered.filter(a=>a.date===date).map(a=><button key={a.id} onClick={()=>onAppointment(a)} className="w-full border-l-2 bg-white/[.04] p-2 text-left" style={{borderColor:barbers.find(b=>b.id===a.barberId)?.color}}><b className="text-xs">{a.time}</b><span className="mt-1 block truncate text-xs">{a.clientName}</span><small className="block truncate text-white/40">{serviceName(a.serviceId)}</small></button>)}{dayBlocks(date).map(block=><div key={block.id} className="group border border-dashed border-amber-300/30 p-2 text-xs text-amber-200/70"><b>{new Date(block.startAt*1000).toLocaleTimeString("es-CO",{timeZone:"America/Bogota",hour:"numeric",minute:"2-digit"})}</b><span className="block truncate">{block.reason}</span><button onClick={()=>onDeleteBlock(block.id)} className="mt-1 text-[10px] text-red-300 opacity-0 group-hover:opacity-100">Eliminar</button></div>)}</div></div>)}</div>}
    {mode==="month"&&<div className="grid grid-cols-7">{dayNames&&["LUN","MAR","MIÉ","JUE","VIE","SÁB","DOM"].map(day=><div key={day} className="border-b border-r border-white/10 p-2 text-center text-[10px] font-bold text-white/35">{day}</div>)}{monthDays.map(date=>{const items=filtered.filter(a=>a.date===date);const inMonth=date.slice(0,7)===focus.slice(0,7);return <button key={date} onClick={()=>{setFocus(date);setMode("day")}} className={`min-h-24 border-b border-r border-white/10 p-2 text-left hover:bg-white/[.035] ${inMonth?"":"opacity-25"}`}><b className={date===today?"text-[#e84c3d]":""}>{parseDate(date).getDate()}</b>{items.slice(0,3).map(a=><span key={a.id} className="mt-1 block truncate bg-white/[.06] px-1.5 py-1 text-[10px]">{a.time} {a.clientName}</span>)}{items.length>3&&<small className="text-white/40">+{items.length-3} más</small>}</button>})}</div>}
  </div>
}

function DayColumn({date,appointments,blocks,serviceName,barberName,onAppointment,onNew,onDeleteBlock}:{date:string;appointments:Appointment[];blocks:Block[];serviceName:(id:string)=>string;barberName:(id:string)=>string;onAppointment:(a:Appointment)=>void;onNew:()=>void;onDeleteBlock:(id:string)=>Promise<void>}){
  return <div className="mx-auto max-w-4xl space-y-2"><div className="mb-5 flex items-center justify-between"><div><h3 className="text-xl font-black capitalize">{dateLabel(date,{weekday:"long",month:"long",day:"numeric"})}</h3><p className="text-sm text-white/40">{appointments.length} citas · {blocks.length} bloqueos</p></div><Button onClick={onNew} className="rounded-none"><Plus/> Cita</Button></div>{appointments.map(a=><button key={a.id} onClick={()=>onAppointment(a)} className="grid w-full gap-2 border border-white/10 p-4 text-left hover:border-[#e84c3d] sm:grid-cols-[110px_1fr_1fr_auto] sm:items-center"><b>{a.time}</b><span><b className="block">{a.clientName}</b><small className="text-white/40">{a.phone}</small></span><span className="text-sm text-white/55">{serviceName(a.serviceId)}<small className="block">{barberName(a.barberId)}</small></span><Status status={a.status}/></button>)}{blocks.map(block=><div key={block.id} className="flex items-center justify-between border border-dashed border-amber-300/30 p-4 text-amber-100/70"><span><b>{new Date(block.startAt*1000).toLocaleTimeString("es-CO",{timeZone:"America/Bogota",hour:"numeric",minute:"2-digit"})} – {new Date(block.endAt*1000).toLocaleTimeString("es-CO",{timeZone:"America/Bogota",hour:"numeric",minute:"2-digit"})}</b><small className="block">{barberName(block.barberId)} · {block.reason}</small></span><button onClick={()=>onDeleteBlock(block.id)} className="text-red-300"><Trash2 size={17}/></button></div>)}{!appointments.length&&!blocks.length&&<Empty title="Día disponible" detail="No hay citas ni bloqueos para esta fecha." action="AGREGAR CITA" onAction={onNew}/>}</div>
}

function ClientsView({clients,appointments,serviceName,barberName,onClient}:{clients:Client[];appointments:Appointment[];serviceName:(id:string)=>string;barberName:(id:string)=>string;onClient:(c:Client)=>void}){
  const [query,setQuery]=useState("");
  const filtered=clients.filter(client=>[client.name,client.phone,client.email??"",client.notes??""].join(" ").toLowerCase().includes(query.toLowerCase()));
  const stats=(client:Client)=>{const rows=appointments.filter(a=>a.clientId===client.id||a.phone===client.phone);const visits=rows.filter(a=>a.status==="completed").length;const spend=rows.filter(a=>a.status==="completed").reduce((sum,a)=>sum+a.price,0);const last=[...rows].filter(a=>a.status==="completed").sort((a,b)=>b.startAt-a.startAt)[0];const next=[...rows].filter(a=>a.startAt>=Date.now()/1000&&activeStatuses.has(a.status)).sort((a,b)=>a.startAt-b.startAt)[0];return{visits,spend,last,next}};
  return <div className="border border-white/10 bg-[#141412]"><div className="flex flex-col gap-4 border-b border-white/10 p-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-xl font-black">{clients.length} clientes</h2><p className="text-sm text-white/40">Cada reserva construye automáticamente el historial.</p></div><div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-white/30" size={16}/><Input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Nombre, teléfono, nota…" className="h-11 w-full rounded-none border-white/10 bg-black/20 pl-10 sm:w-72"/></div></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="border-b border-white/10 text-xs text-white/35"><tr><th className="p-4">CLIENTE</th><th className="p-4">PREFERENCIA</th><th className="p-4">VISITAS</th><th className="p-4">VALOR</th><th className="p-4">ÚLTIMA / PRÓXIMA</th><th className="p-4"></th></tr></thead><tbody className="divide-y divide-white/10">{filtered.map(client=>{const item=stats(client);return <tr key={client.id} className="hover:bg-white/[.025]"><td className="p-4"><b>{client.name}</b><small className="block text-white/40">{client.phone}{client.email?` · ${client.email}`:""}</small></td><td className="p-4 text-sm">{client.preferredBarber?barberName(client.preferredBarber):"Sin preferencia"}</td><td className="p-4 font-bold">{item.visits}</td><td className="p-4 font-bold">{money(item.spend)}</td><td className="p-4 text-sm"><span className="block text-white/55">{item.last?`Última: ${dateLabel(item.last.date)} · ${serviceName(item.last.serviceId)}`:"Primera visita pendiente"}</span><span className="block text-[#ff7164]">{item.next?`Próxima: ${dateLabel(item.next.date)} · ${item.next.time}`:"Sin próxima cita"}</span></td><td className="p-4"><button onClick={()=>onClient(client)} className="border border-white/10 p-2 hover:border-[#e84c3d]" aria-label={`Editar ${client.name}`}><Pencil size={16}/></button></td></tr>})}</tbody></table>{!filtered.length&&<Empty title="Sin resultados" detail="Prueba otro nombre, teléfono o nota."/>}</div></div>
}

function ServicesView({services,onEdit}:{services:ServiceRow[];onEdit:(s:ServiceRow)=>void}){return <div><div className="mb-5 flex items-end justify-between"><div><h2 className="text-xl font-black">{services.filter(s=>s.active).length} servicios activos</h2><p className="text-sm text-white/40">El precio y la duración guardados se usan en nuevas reservas.</p></div></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{services.map(service=><article key={service.id} className={`border bg-[#141412] p-5 ${service.active?"border-white/10":"border-white/5 opacity-55"}`}><div className="flex items-start justify-between"><span className="text-xs font-bold uppercase tracking-widest text-white/30">{service.id}</span><span className={`px-2 py-1 text-[10px] font-bold ${service.active?"bg-emerald-400/15 text-emerald-300":"bg-white/10 text-white/45"}`}>{service.active?"ACTIVO":"OCULTO"}</span></div><h3 className="mt-5 text-2xl font-black">{service.nameEs}</h3><p className="mt-1 text-sm text-white/40">{service.nameEn}</p><div className="mt-6 flex items-end justify-between"><span><b className="block text-xl">{money(service.price)}</b><small className="text-white/40">{service.minutes} minutos{service.featured?" · destacado":""}</small></span><button onClick={()=>onEdit(service)} className="grid h-11 w-11 place-items-center border border-white/10 hover:border-[#e84c3d]" aria-label={`Editar ${service.nameEs}`}><Pencil size={17}/></button></div></article>)}</div></div>}

function TeamView({barbers,appointments,today,onEdit,onBlock}:{barbers:BarberRow[];appointments:Appointment[];today:string;onEdit:(b:BarberRow)=>void;onBlock:()=>void}){return <div className="grid gap-5 lg:grid-cols-2">{barbers.map(barber=>{const todays=appointments.filter(a=>a.date===today&&a.barberId===barber.id&&!["cancelled","no_show"].includes(a.status));const upcoming=appointments.filter(a=>a.startAt>=Date.now()/1000&&a.barberId===barber.id&&activeStatuses.has(a.status));return <article key={barber.id} className="border border-white/10 bg-[#141412] p-6"><div className="flex items-start justify-between"><div className="flex items-center gap-4"><span className="grid h-14 w-14 place-items-center text-xl font-black text-black" style={{background:barber.color}}>{initials(barber.name)}</span><span><h2 className="text-2xl font-black">{barber.name}</h2><p className="text-sm text-white/40">{barber.handle||"Sin Instagram"}</p></span></div><span className={`px-2 py-1 text-[10px] font-bold ${barber.active?"bg-emerald-400/15 text-emerald-300":"bg-white/10 text-white/40"}`}>{barber.active?"ACTIVO":"INACTIVO"}</span></div><p className="mt-6 text-white/60">{barber.specialties||"Especialidades pendientes"}</p><div className="mt-6 grid grid-cols-3 border-y border-white/10 py-5 text-center"><span><b className="block text-2xl">{todays.length}</b><small className="text-white/35">HOY</small></span><span><b className="block text-2xl">{upcoming.length}</b><small className="text-white/35">PRÓXIMAS</small></span><span><b className="block text-2xl">{barber.phone?"✓":"—"}</b><small className="text-white/35">CONTACTO</small></span></div><div className="mt-5 grid grid-cols-2 gap-2"><button onClick={()=>onEdit(barber)} className="h-11 border border-white/10 text-sm font-bold hover:border-[#e84c3d]"><Pencil className="mr-2 inline" size={15}/> EDITAR</button><button onClick={onBlock} className="h-11 border border-white/10 text-sm font-bold hover:border-[#e84c3d]"><Clock3 className="mr-2 inline" size={15}/> BLOQUEAR</button></div></article>})}</div>}

function SettingsView({settings,onSave}:{settings:Record<string,string>;onSave:(value:Record<string,string>)=>Promise<void>}){const [form,setForm]=useState(settings);const [saving,setSaving]=useState(false);useEffect(()=>setForm(settings),[settings]);const field=(key:string,value:string)=>setForm(current=>({...current,[key]:value}));const save=async()=>{setSaving(true);try{await onSave(form)}finally{setSaving(false)}};return <div className="grid gap-5 xl:grid-cols-[1fr_360px]"><div className="space-y-5"><Panel title="Estudio" subtitle="Información operativa y contacto"><div className="grid gap-4 sm:grid-cols-2"><Field label="Nombre"><Input value={form.businessName??""} onChange={e=>field("businessName",e.target.value)}/></Field><Field label="WhatsApp"><Input value={form.whatsapp??""} onChange={e=>field("whatsapp",e.target.value)}/></Field><Field label="Dirección" wide><Input value={form.address??""} onChange={e=>field("address",e.target.value)}/></Field></div></Panel><Panel title="Reglas de reserva" subtitle="Estas reglas controlan disponibilidad y conflictos"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Field label="Anticipación mínima (min)"><Input type="number" min="0" value={form.bookingLeadMinutes??"60"} onChange={e=>field("bookingLeadMinutes",e.target.value)}/></Field><Field label="Ventana de reserva (días)"><Input type="number" min="1" value={form.bookingWindowDays??"45"} onChange={e=>field("bookingWindowDays",e.target.value)}/></Field><Field label="Intervalo de horarios (min)"><Input type="number" min="5" step="5" value={form.slotInterval??"15"} onChange={e=>field("slotInterval",e.target.value)}/></Field><Field label="Buffer entre citas (min)"><Input type="number" min="0" step="5" value={form.bufferMinutes??"0"} onChange={e=>field("bufferMinutes",e.target.value)}/></Field><Field label="Cancelación mínima (horas)"><Input type="number" min="0" value={form.cancellationHours??"4"} onChange={e=>field("cancellationHours",e.target.value)}/></Field></div></Panel><Panel title="Horario general" subtitle="Los horarios individuales del equipo pueden ser más restrictivos"><div className="grid gap-4 sm:grid-cols-2"><Field label="Apertura"><Input type="time" value={form.openingTime??"09:15"} onChange={e=>field("openingTime",e.target.value)}/></Field><Field label="Cierre"><Input type="time" value={form.closingTime??"20:20"} onChange={e=>field("closingTime",e.target.value)}/></Field></div><div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-4 lg:grid-cols-7">{dayKeys.map(day=><button key={day} onClick={()=>field(day,form[day]==="closed"?"open":"closed")} className={`h-12 border text-sm font-bold ${form[day]==="closed"?"border-white/10 text-white/30":"border-[#e84c3d] bg-[#e84c3d]/10 text-[#ff7164]"}`}>{dayNames[day]}<small className="ml-1">{form[day]==="closed"?"Cerrado":"Abierto"}</small></button>)}</div></Panel><Button onClick={save} disabled={saving} className="h-13 rounded-none px-8 font-black">{saving?"GUARDANDO…":"GUARDAR CONFIGURACIÓN"} <Check/></Button></div><aside className="h-fit border border-[#e84c3d]/25 bg-[#e84c3d]/[.06] p-6 xl:sticky xl:top-24"><p className="eyebrow text-[#ff7164]">IMPACTO EN TIEMPO REAL</p><h3 className="mt-4 text-2xl font-black">La agenda obedece estas reglas</h3><ul className="mt-5 space-y-3 text-sm leading-relaxed text-white/55"><li>• Los clientes solo ven horarios válidos.</li><li>• Duración y buffer evitan cruces.</li><li>• Días cerrados desaparecen de disponibilidad.</li><li>• Los bloqueos de cada barbero tienen prioridad.</li></ul></aside></div>}

function Panel({title,subtitle,children}:{title:string;subtitle:string;children:React.ReactNode}){return <section className="border border-white/10 bg-[#141412] p-5 sm:p-6"><h2 className="text-xl font-black">{title}</h2><p className="mt-1 mb-6 text-sm text-white/40">{subtitle}</p>{children}</section>}
function Field({label,children,wide=false}:{label:string;children:React.ReactNode;wide?:boolean}){return <label className={wide?"sm:col-span-2":""}><span className="mb-2 block text-sm font-semibold text-white/55">{label}</span>{children}</label>}
function Empty({title,detail,action,onAction}:{title:string;detail:string;action?:string;onAction?:()=>void}){return <div className="grid min-h-44 place-items-center p-8 text-center"><div><h3 className="font-black">{title}</h3><p className="mt-2 text-sm text-white/40">{detail}</p>{action&&onAction&&<button onClick={onAction} className="mt-5 border-b border-[#e84c3d] pb-1 text-xs font-black text-[#ff7164]">{action}</button>}</div></div>}

function AppointmentDialog({open,onOpenChange,appointment,services,barbers,onSaved}:{open:boolean;onOpenChange:(v:boolean)=>void;appointment:Appointment|null;services:ServiceRow[];barbers:BarberRow[];onSaved:()=>void}){
  const blank={name:"",phone:"",email:"",serviceId:services[0]?.id??"",barberId:barbers[0]?.id??"",date:dateInput(new Date()),time:"09:15",status:"confirmed",notes:""};
  const [form,setForm]=useState(blank);const [saving,setSaving]=useState(false);const [error,setError]=useState("");
  useEffect(()=>{setForm(appointment?{name:appointment.clientName,phone:appointment.phone,email:appointment.email??"",serviceId:appointment.serviceId,barberId:appointment.barberId,date:appointment.date,time:to24Input(appointment.time),status:appointment.status,notes:appointment.notes??""}:blank);setError("")},[appointment,open,services.length,barbers.length]);
  const save=async(event:FormEvent)=>{event.preventDefault();setSaving(true);setError("");try{await api("/api/admin/appointments",{method:appointment?"PATCH":"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...form,time:to12Label(form.time),...(appointment?{id:appointment.id}:{})})});onSaved()}catch(error){setError(error instanceof Error?error.message:"No pudimos guardar.")}finally{setSaving(false)}};
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-[#151513] text-white sm:max-w-2xl"><DialogHeader><DialogTitle>{appointment?"Editar cita":"Nueva cita / Walk-in"}</DialogTitle><DialogDescription className="text-white/40">Guarda la cita directamente en el calendario real del estudio.</DialogDescription></DialogHeader><form onSubmit={save} className="mt-2 grid gap-4 sm:grid-cols-2"><Field label="Nombre"><Input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="WhatsApp"><Input required value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></Field><Field label="Email"><Input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field><Field label="Servicio"><select required value={form.serviceId} onChange={e=>setForm({...form,serviceId:e.target.value})} className="h-10 w-full border border-white/10 bg-[#111] px-3">{services.map(s=><option key={s.id} value={s.id}>{s.nameEs} · {s.minutes} min</option>)}</select></Field><Field label="Barbero"><select required value={form.barberId} onChange={e=>setForm({...form,barberId:e.target.value})} className="h-10 w-full border border-white/10 bg-[#111] px-3">{barbers.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></Field><Field label="Estado"><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})} className="h-10 w-full border border-white/10 bg-[#111] px-3">{Object.entries(statusMap).map(([value,item])=><option key={value} value={value}>{item.label}</option>)}</select></Field><Field label="Fecha"><Input required type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></Field><Field label="Hora"><Input required type="time" step="300" value={form.time} onChange={e=>setForm({...form,time:e.target.value})}/></Field><Field label="Notas" wide><Textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})} className="min-h-24"/></Field>{error&&<p className="border border-red-400/25 bg-red-400/10 p-3 text-sm text-red-200 sm:col-span-2">{error}</p>}<div className="flex flex-wrap gap-2 sm:col-span-2">{appointment&&["arrived","in_progress","completed","no_show","cancelled"].map(status=><button type="button" key={status} onClick={()=>setForm({...form,status})} className="border border-white/10 px-3 py-2 text-xs hover:border-[#e84c3d]">{statusMap[status].label}</button>)}<Button disabled={saving} className="ml-auto h-11 rounded-none px-6">{saving?"GUARDANDO…":"GUARDAR CITA"} <Check/></Button></div></form></DialogContent></Dialog>
}

function BlockDialog({open,onOpenChange,barbers,onSaved}:{open:boolean;onOpenChange:(v:boolean)=>void;barbers:BarberRow[];onSaved:()=>void}){const [form,setForm]=useState({barberId:"",date:dateInput(new Date()),startTime:"12:00",endTime:"13:00",reason:"Almuerzo"});const [saving,setSaving]=useState(false);const [error,setError]=useState("");useEffect(()=>{if(!form.barberId&&barbers[0])setForm(current=>({...current,barberId:barbers[0].id}))},[barbers,form.barberId]);const save=async(e:FormEvent)=>{e.preventDefault();setSaving(true);setError("");try{await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"block:create",...form})});onSaved()}catch(error){setError(error instanceof Error?error.message:"No pudimos bloquear el tiempo.")}finally{setSaving(false)}};return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="border-white/10 bg-[#151513] text-white"><DialogHeader><DialogTitle>Bloquear tiempo</DialogTitle><DialogDescription className="text-white/40">Cierra un espacio para almuerzo, asuntos personales, reuniones o vacaciones.</DialogDescription></DialogHeader><form onSubmit={save} className="mt-3 grid gap-4 sm:grid-cols-2"><Field label="Barbero"><select value={form.barberId} onChange={e=>setForm({...form,barberId:e.target.value})} className="h-10 w-full border border-white/10 bg-[#111] px-3">{barbers.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></Field><Field label="Fecha"><Input type="date" required value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></Field><Field label="Desde"><Input type="time" required value={form.startTime} onChange={e=>setForm({...form,startTime:e.target.value})}/></Field><Field label="Hasta"><Input type="time" required value={form.endTime} onChange={e=>setForm({...form,endTime:e.target.value})}/></Field><Field label="Motivo" wide><select value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})} className="h-10 w-full border border-white/10 bg-[#111] px-3"><option>Almuerzo</option><option>Personal</option><option>Reunión</option><option>Vacaciones</option><option>No disponible</option></select></Field>{error&&<p className="border border-red-400/25 bg-red-400/10 p-3 text-sm text-red-200 sm:col-span-2">{error}</p>}<Button disabled={saving} className="h-11 rounded-none sm:col-span-2">{saving?"BLOQUEANDO…":"BLOQUEAR TIEMPO"} <Clock3/></Button></form></DialogContent></Dialog>}

function WaitlistDialog({open,onOpenChange,entries,services,barbers,onChanged}:{open:boolean;onOpenChange:(v:boolean)=>void;entries:WaitlistEntry[];services:ServiceRow[];barbers:BarberRow[];onChanged:(message:string)=>void}){const [adding,setAdding]=useState(false);const [form,setForm]=useState({name:"",phone:"",serviceId:"",barberId:"",preferredDate:dateInput(new Date()),preferredTime:""});const [error,setError]=useState("");const serviceName=(id:string)=>services.find(s=>s.id===id)?.nameEs??id;const barberName=(id?:string|null)=>barbers.find(b=>b.id===id)?.name??"Cualquier barbero";useEffect(()=>{if(!form.serviceId&&services[0])setForm(current=>({...current,serviceId:services[0].id}))},[services,form.serviceId]);const act=async(payload:Record<string,unknown>,message:string)=>{try{await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});onChanged(message)}catch(error){setError(error instanceof Error?error.message:"No pudimos actualizar la lista.")}};return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-[#151513] text-white sm:max-w-3xl"><DialogHeader><DialogTitle>Lista de espera</DialogTitle><DialogDescription className="text-white/40">Convierte cancelaciones en reservas antes de perder el espacio.</DialogDescription></DialogHeader><div className="mt-3 flex justify-between"><span className="text-sm text-white/45">{entries.filter(e=>e.status==="waiting").length} esperando</span><button onClick={()=>setAdding(!adding)} className="text-xs font-black text-[#ff7164]"><Plus className="mr-1 inline" size={15}/> AGREGAR CLIENTE</button></div>{adding&&<form onSubmit={async e=>{e.preventDefault();await act({action:"waitlist:create",...form,barberId:form.barberId||null,preferredTime:form.preferredTime||null},"Cliente agregado a la lista de espera.");setAdding(false);setForm({...form,name:"",phone:""})}} className="mt-4 grid gap-3 border border-[#e84c3d]/25 bg-[#e84c3d]/[.05] p-4 sm:grid-cols-2"><Input required placeholder="Nombre" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><Input required placeholder="WhatsApp" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/><select value={form.serviceId} onChange={e=>setForm({...form,serviceId:e.target.value})} className="h-10 border border-white/10 bg-[#111] px-3">{services.map(s=><option key={s.id} value={s.id}>{s.nameEs}</option>)}</select><select value={form.barberId} onChange={e=>setForm({...form,barberId:e.target.value})} className="h-10 border border-white/10 bg-[#111] px-3"><option value="">Cualquier barbero</option>{barbers.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><Input type="date" value={form.preferredDate} onChange={e=>setForm({...form,preferredDate:e.target.value})}/><Input type="time" value={form.preferredTime} onChange={e=>setForm({...form,preferredTime:e.target.value})}/><Button className="rounded-none sm:col-span-2">GUARDAR EN ESPERA</Button></form>}<div className="mt-4 space-y-2">{entries.map(entry=><div key={entry.id} className="grid gap-3 border border-white/10 p-4 sm:grid-cols-[1fr_1fr_auto] sm:items-center"><span><b>{entry.name}</b><a href={`https://wa.me/${entry.phone.replace(/\D/g,"")}`} target="_blank" rel="noreferrer" className="block text-sm text-[#ff7164]">{entry.phone}</a></span><span className="text-sm text-white/55">{serviceName(entry.serviceId)} · {barberName(entry.barberId)}<small className="block">{dateLabel(entry.preferredDate)} {entry.preferredTime??""}</small></span><span className="flex gap-1">{entry.status==="waiting"&&<button onClick={()=>act({action:"waitlist:update",id:entry.id,status:"contacted"},"Cliente marcado como contactado.")} className="border border-white/10 px-2 py-2 text-xs">CONTACTADO</button>}<button onClick={()=>act({action:"waitlist:update",id:entry.id,status:"booked"},"Cliente marcado como reservado.")} className="border border-white/10 px-2 py-2 text-xs">RESERVADO</button><button onClick={()=>act({action:"waitlist:delete",id:entry.id},"Cliente eliminado de la lista.")} className="border border-white/10 p-2 text-red-300"><Trash2 size={15}/></button></span></div>)}{!entries.length&&<Empty title="Lista vacía" detail="Agrega clientes cuando su horario preferido esté lleno."/>}</div>{error&&<p className="mt-3 text-sm text-red-300">{error}</p>}</DialogContent></Dialog>}

function SearchDialog({open,onOpenChange,data,serviceName,barberName,onAppointment,onClient}:{open:boolean;onOpenChange:(v:boolean)=>void;data:StudioData;serviceName:(id:string)=>string;barberName:(id:string)=>string;onAppointment:(a:Appointment)=>void;onClient:(c:Client)=>void}){const [query,setQuery]=useState("");useEffect(()=>{if(open)setQuery("")},[open]);const needle=query.trim().toLowerCase();const appointments=needle?data.appointments.filter(a=>[a.clientName,a.phone,a.email??"",a.date,a.time,serviceName(a.serviceId),barberName(a.barberId)].join(" ").toLowerCase().includes(needle)).slice(0,8):[];const clients=needle?data.clients.filter(c=>[c.name,c.phone,c.email??"",c.notes??""].join(" ").toLowerCase().includes(needle)).slice(0,8):[];return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[85vh] overflow-y-auto border-white/10 bg-[#151513] text-white sm:max-w-2xl"><DialogHeader><DialogTitle>Buscar en Studio OS</DialogTitle><DialogDescription className="text-white/40">Encuentra una cita o cliente por nombre, teléfono, fecha, servicio o barbero.</DialogDescription></DialogHeader><div className="relative mt-2"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-white/30" size={19}/><Input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ej. Carlos, 321…, VIP, Cheo…" className="h-13 rounded-none border-white/15 bg-black/25 pl-12"/></div>{needle&&<div className="mt-4 space-y-5"><div><p className="eyebrow mb-2 text-white/30">CITAS</p>{appointments.map(a=><button key={a.id} onClick={()=>onAppointment(a)} className="flex w-full items-center justify-between border-b border-white/10 p-3 text-left hover:bg-white/[.03]"><span><b>{a.clientName}</b><small className="block text-white/40">{serviceName(a.serviceId)} · {barberName(a.barberId)}</small></span><span className="text-sm">{a.date}<small className="block text-right text-white/40">{a.time}</small></span></button>)}{!appointments.length&&<p className="p-3 text-sm text-white/35">Sin citas encontradas.</p>}</div><div><p className="eyebrow mb-2 text-white/30">CLIENTES</p>{clients.map(c=><button key={c.id} onClick={()=>onClient(c)} className="flex w-full items-center justify-between border-b border-white/10 p-3 text-left hover:bg-white/[.03]"><span><b>{c.name}</b><small className="block text-white/40">{c.phone}</small></span><ArrowRight size={17}/></button>)}{!clients.length&&<p className="p-3 text-sm text-white/35">Sin clientes encontrados.</p>}</div></div>}</DialogContent></Dialog>}

function ClientDialog({client,open,onOpenChange,barbers,appointments,serviceName,onSaved}:{client:Client|null;open:boolean;onOpenChange:(v:boolean)=>void;barbers:BarberRow[];appointments:Appointment[];serviceName:(id:string)=>string;onSaved:()=>void}){const [form,setForm]=useState({name:"",email:"",preferredBarber:"",notes:""});const [saving,setSaving]=useState(false);useEffect(()=>{if(client)setForm({name:client.name,email:client.email??"",preferredBarber:client.preferredBarber??"",notes:client.notes??""})},[client]);if(!client)return null;const history=appointments.filter(a=>a.clientId===client.id||a.phone===client.phone).sort((a,b)=>b.startAt-a.startAt);const save=async()=>{setSaving(true);try{await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"client:save",id:client.id,...form,email:form.email||null,preferredBarber:form.preferredBarber||null})});onSaved()}finally{setSaving(false)}};return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-[#151513] text-white sm:max-w-2xl"><DialogHeader><DialogTitle>{client.name}</DialogTitle><DialogDescription className="text-white/40">{client.phone} · {history.length} reservas registradas</DialogDescription></DialogHeader><div className="mt-3 grid gap-4 sm:grid-cols-2"><Field label="Nombre"><Input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Email"><Input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field><Field label="Barbero preferido" wide><select value={form.preferredBarber} onChange={e=>setForm({...form,preferredBarber:e.target.value})} className="h-10 w-full border border-white/10 bg-[#111] px-3"><option value="">Sin preferencia</option>{barbers.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></Field><Field label="Notas internas" wide><Textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})} placeholder="Preferencias de corte, piel sensible, detalles importantes…" className="min-h-24"/></Field><Button onClick={save} disabled={saving} className="rounded-none sm:col-span-2">{saving?"GUARDANDO…":"GUARDAR PERFIL"}</Button></div><div className="mt-6"><p className="eyebrow mb-3 text-white/30">HISTORIAL</p><div className="max-h-52 space-y-2 overflow-y-auto">{history.map(a=><div key={a.id} className="flex justify-between border border-white/10 p-3 text-sm"><span><b>{dateLabel(a.date)} · {a.time}</b><small className="block text-white/40">{serviceName(a.serviceId)}</small></span><Status status={a.status}/></div>)}{!history.length&&<p className="text-sm text-white/35">Sin historial todavía.</p>}</div></div></DialogContent></Dialog>}

function ServiceDialog({service,open,onOpenChange,onSaved}:{service:ServiceRow|null;open:boolean;onOpenChange:(v:boolean)=>void;onSaved:()=>void}){const [form,setForm]=useState<ServiceRow|null>(service);const [saving,setSaving]=useState(false);const [error,setError]=useState("");useEffect(()=>{setForm(service);setError("")},[service]);if(!form)return null;const save=async()=>{setSaving(true);setError("");try{await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"service:save",value:form})});onSaved()}catch(error){setError(error instanceof Error?error.message:"No pudimos guardar.")}finally{setSaving(false)}};return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="border-white/10 bg-[#151513] text-white"><DialogHeader><DialogTitle>Editar servicio</DialogTitle><DialogDescription className="text-white/40">Los cambios controlan el precio, duración y disponibilidad del motor de reservas.</DialogDescription></DialogHeader><div className="mt-3 grid gap-4 sm:grid-cols-2"><Field label="Nombre en español"><Input value={form.nameEs} onChange={e=>setForm({...form,nameEs:e.target.value})}/></Field><Field label="Nombre en inglés"><Input value={form.nameEn} onChange={e=>setForm({...form,nameEn:e.target.value})}/></Field><Field label="Precio COP"><Input type="number" step="1000" value={form.price} onChange={e=>setForm({...form,price:Number(e.target.value)})}/></Field><Field label="Duración (min)"><Input type="number" step="5" value={form.minutes} onChange={e=>setForm({...form,minutes:Number(e.target.value)})}/></Field><label className="flex items-center justify-between border border-white/10 p-4"><span><b className="block text-sm">Servicio activo</b><small className="text-white/35">Visible al reservar</small></span><Switch checked={form.active} onCheckedChange={active=>setForm({...form,active})}/></label><label className="flex items-center justify-between border border-white/10 p-4"><span><b className="block text-sm">Destacado</b><small className="text-white/35">Prioridad comercial</small></span><Switch checked={form.featured} onCheckedChange={featured=>setForm({...form,featured})}/></label>{error&&<p className="text-sm text-red-300 sm:col-span-2">{error}</p>}<Button onClick={save} disabled={saving} className="rounded-none sm:col-span-2">{saving?"GUARDANDO…":"GUARDAR SERVICIO"}</Button></div></DialogContent></Dialog>}

function BarberDialog({barber,open,onOpenChange,onSaved}:{barber:BarberRow|null;open:boolean;onOpenChange:(v:boolean)=>void;onSaved:()=>void}){const [form,setForm]=useState<BarberRow|null>(barber);const [days,setDays]=useState<Record<string,boolean>>({});const [start,setStart]=useState("09:15");const [end,setEnd]=useState("20:20");const [saving,setSaving]=useState(false);const [error,setError]=useState("");useEffect(()=>{if(!barber)return;setForm(barber);try{const hours=JSON.parse(barber.workingHours||"{}") as Record<string,[string,string]|null>;setDays(Object.fromEntries(dayKeys.map(day=>[day,hours[day]!==null])));const first=dayKeys.map(day=>hours[day]).find(Boolean);if(first){setStart(first[0]);setEnd(first[1])}}catch{setDays(Object.fromEntries(dayKeys.map(day=>[day,day!=="sunday"])))}setError("")},[barber]);if(!form)return null;const save=async()=>{setSaving(true);setError("");try{const workingHours=JSON.stringify(Object.fromEntries(dayKeys.map(day=>[day,days[day]?[start,end]:null])));await api("/api/admin/studio",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"barber:save",value:{...form,workingHours}})});onSaved()}catch(error){setError(error instanceof Error?error.message:"No pudimos guardar.")}finally{setSaving(false)}};return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-[#151513] text-white sm:max-w-2xl"><DialogHeader><DialogTitle>Editar barbero</DialogTitle><DialogDescription className="text-white/40">Controla identidad, disponibilidad y capacidad individual.</DialogDescription></DialogHeader><div className="mt-3 grid gap-4 sm:grid-cols-2"><Field label="Nombre"><Input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Instagram"><Input value={form.handle??""} onChange={e=>setForm({...form,handle:e.target.value})}/></Field><Field label="WhatsApp"><Input value={form.phone??""} onChange={e=>setForm({...form,phone:e.target.value})}/></Field><Field label="Color en calendario"><Input type="color" value={form.color} onChange={e=>setForm({...form,color:e.target.value})} className="p-1"/></Field><Field label="Especialidades" wide><Input value={form.specialties??""} onChange={e=>setForm({...form,specialties:e.target.value})}/></Field><label className="flex items-center justify-between border border-white/10 p-4 sm:col-span-2"><span><b className="block text-sm">Recibe reservas</b><small className="text-white/35">Desactívalo durante una ausencia larga</small></span><Switch checked={form.active} onCheckedChange={active=>setForm({...form,active})}/></label><div className="sm:col-span-2"><p className="mb-3 text-sm font-semibold text-white/55">Días de trabajo</p><div className="grid grid-cols-4 gap-2 sm:grid-cols-7">{dayKeys.map(day=><button key={day} onClick={()=>setDays({...days,[day]:!days[day]})} className={`h-10 border text-xs font-bold ${days[day]?"border-[#e84c3d] bg-[#e84c3d]/10 text-[#ff7164]":"border-white/10 text-white/30"}`}>{dayNames[day]}</button>)}</div></div><Field label="Entrada"><Input type="time" value={start} onChange={e=>setStart(e.target.value)}/></Field><Field label="Salida"><Input type="time" value={end} onChange={e=>setEnd(e.target.value)}/></Field>{error&&<p className="text-sm text-red-300 sm:col-span-2">{error}</p>}<Button onClick={save} disabled={saving} className="rounded-none sm:col-span-2">{saving?"GUARDANDO…":"GUARDAR BARBERO"}</Button></div></DialogContent></Dialog>}

function to24Input(value:string){const match=value.match(/(\d+):(\d+)\s*(AM|PM)/i);if(!match)return value;let hour=Number(match[1]);if(match[3].toUpperCase()==="PM"&&hour!==12)hour+=12;if(match[3].toUpperCase()==="AM"&&hour===12)hour=0;return `${String(hour).padStart(2,"0")}:${match[2]}`}
function to12Label(value:string){const [hourValue,minute]=value.split(":").map(Number);const suffix=hourValue>=12?"PM":"AM";return `${hourValue%12||12}:${String(minute).padStart(2,"0")} ${suffix}`}
